`timescale 1ns/1ps
// apb_gpio: APB4 GPIO peripheral with interrupts.
// Implements interface_spec.md and microarchitecture.md (approved).
module apb_gpio #(
  parameter integer ADDR_WIDTH = 8,
  parameter integer N          = 8
) (
  input  wire                  pclk,
  input  wire                  presetn,
  input  wire [ADDR_WIDTH-1:0] paddr,
  input  wire                  psel,
  input  wire                  penable,
  input  wire                  pwrite,
  input  wire [31:0]           pwdata,
  input  wire [3:0]            pstrb,
  output reg  [31:0]           prdata,
  output wire                  pready,
  output wire                  pslverr,
  input  wire [N-1:0]          gpio_in,
  output wire [N-1:0]          gpio_out,
  output wire [N-1:0]          gpio_oe,
  output wire                  irq
);

  // Bits 0..N-1 set: the pins that exist.
  localparam [31:0] PINS = 32'hFFFF_FFFF >> (32 - N);

  // Register indices (paddr[5:2]).
  localparam [3:0] R_DATA_OUT    = 4'd0;
  localparam [3:0] R_DIR         = 4'd1;
  localparam [3:0] R_DATA_IN     = 4'd2;
  localparam [3:0] R_INTR_RISE   = 4'd3;
  localparam [3:0] R_INTR_FALL   = 4'd4;
  localparam [3:0] R_INTR_HIGH   = 4'd5;
  localparam [3:0] R_INTR_LOW    = 4'd6;
  localparam [3:0] R_INTR_ENABLE = 4'd7;
  localparam [3:0] R_INTR_STATUS = 4'd8;

  // ---------------------------------------------------------------- APB decode
  wire                  access  = psel & penable;
  wire [3:0]            idx     = paddr[5:2];
  wire [ADDR_WIDTH-1:0] addr_hi = paddr >> 6;
  wire                  hi_zero = (addr_hi == {ADDR_WIDTH{1'b0}});
  wire                  mapped  = (paddr[1:0] == 2'b00) & hi_zero & (idx <= R_INTR_STATUS);

  wire wr = access & pwrite & mapped;
  wire rd = access & ~pwrite & mapped;

  assign pready  = 1'b1;
  assign pslverr = access & (~mapped | (pwrite & (idx == R_DATA_IN)));

  wire [31:0] wmask = {{8{pstrb[3]}}, {8{pstrb[2]}}, {8{pstrb[1]}}, {8{pstrb[0]}}} & PINS;

  // ---------------------------------------------------------------- registers
  reg [31:0] data_out, dir, intr_rise, intr_fall, intr_high, intr_low, intr_en, status;
  reg [31:0] in_q, in_prev;

  reg [31:0] data_out_n, dir_n, intr_rise_n, intr_fall_n, intr_high_n, intr_low_n, intr_en_n;
  reg [31:0] status_n;

  // gpio_in widened to 32 bits with zeros above N.
  wire [31:0] in_wide;
  generate
    if (N < 32) begin : g_pad
      assign in_wide = {{(32-N){1'b0}}, gpio_in};
    end else begin : g_full
      assign in_wide = gpio_in;
    end
  endgenerate

  // ---------------------------------------------------------------- detection
  wire [31:0] rise     = in_q & ~in_prev;
  wire [31:0] fall     = ~in_q & in_prev;
  wire [31:0] detected = ((rise & intr_rise) | (fall & intr_fall)
                         | (in_q & intr_high) | (~in_q & intr_low)) & PINS;
  wire [31:0] clear    = (wr && (idx == R_INTR_STATUS)) ? (pwdata & wmask) : 32'h0;

  // ---------------------------------------------------------------- next state
  always @* begin
    data_out_n  = data_out;
    dir_n       = dir;
    intr_rise_n = intr_rise;
    intr_fall_n = intr_fall;
    intr_high_n = intr_high;
    intr_low_n  = intr_low;
    intr_en_n   = intr_en;
    if (wr) begin
      case (idx)
        R_DATA_OUT:    data_out_n  = (data_out  & ~wmask) | (pwdata & wmask);
        R_DIR:         dir_n       = (dir       & ~wmask) | (pwdata & wmask);
        R_INTR_RISE:   intr_rise_n = (intr_rise & ~wmask) | (pwdata & wmask);
        R_INTR_FALL:   intr_fall_n = (intr_fall & ~wmask) | (pwdata & wmask);
        R_INTR_HIGH:   intr_high_n = (intr_high & ~wmask) | (pwdata & wmask);
        R_INTR_LOW:    intr_low_n  = (intr_low  & ~wmask) | (pwdata & wmask);
        R_INTR_ENABLE: intr_en_n   = (intr_en   & ~wmask) | (pwdata & wmask);
        default:       data_out_n  = data_out;
      endcase
    end
    // Detection is ORed last: a detection beats a clear.
    status_n = (status & ~clear) | detected;
  end

  // ---------------------------------------------------------------- flops
  always @(posedge pclk) begin
    if (!presetn) begin
      data_out  <= 32'h0;
      dir       <= 32'h0;
      intr_rise <= 32'h0;
      intr_fall <= 32'h0;
      intr_high <= 32'h0;
      intr_low  <= 32'h0;
      intr_en   <= 32'h0;
      status    <= 32'h0;
      in_q      <= 32'h0;
      in_prev   <= 32'h0;
    end else begin
      data_out  <= data_out_n;
      dir       <= dir_n;
      intr_rise <= intr_rise_n;
      intr_fall <= intr_fall_n;
      intr_high <= intr_high_n;
      intr_low  <= intr_low_n;
      intr_en   <= intr_en_n;
      status    <= status_n;
      in_q      <= in_wide;
      in_prev   <= in_q;
    end
  end

  // ---------------------------------------------------------------- read mux
  reg [31:0] rdata;
  always @* begin
    case (idx)
      R_DATA_OUT:    rdata = data_out;
      R_DIR:         rdata = dir;
      R_DATA_IN:     rdata = in_q;
      R_INTR_RISE:   rdata = intr_rise;
      R_INTR_FALL:   rdata = intr_fall;
      R_INTR_HIGH:   rdata = intr_high;
      R_INTR_LOW:    rdata = intr_low;
      R_INTR_ENABLE: rdata = intr_en;
      R_INTR_STATUS: rdata = status;
      default:       rdata = 32'h0;
    endcase
    prdata = rd ? rdata : 32'h0;
  end

  // ---------------------------------------------------------------- outputs
  assign gpio_out = data_out[N-1:0];
  assign gpio_oe  = dir[N-1:0];
  assign irq      = |(status & intr_en);

`ifdef FORMAL
  // Design-intent assertions (no proof setup is submitted with this delivery).
  always @(*) begin
    assert (pready == 1'b1);
    if (!access) begin
      assert (pslverr == 1'b0);
      assert (prdata == 32'h0);
    end
    assert ((status & ~PINS) == 32'h0);
    assert (irq == |(status & intr_en));
  end
`endif

endmodule
=== END FILE ===
