`timescale 1ns/1ps
// Self-checking testbench for apb_gpio, N = 8 and N = 32.
module apb_gpio_tb;

  localparam [7:0] A_DOUT = 8'h00;
  localparam [7:0] A_DIR  = 8'h04;
  localparam [7:0] A_DIN  = 8'h08;
  localparam [7:0] A_RISE = 8'h0C;
  localparam [7:0] A_FALL = 8'h10;
  localparam [7:0] A_HIGH = 8'h14;
  localparam [7:0] A_LOW  = 8'h18;
  localparam [7:0] A_EN   = 8'h1C;
  localparam [7:0] A_STAT = 8'h20;

  reg         pclk = 1'b0;
  reg         presetn = 1'b0;
  reg  [7:0]  paddr = 8'h00;
  reg         psel8 = 1'b0;
  reg         psel32 = 1'b0;
  reg         penable = 1'b0;
  reg         pwrite = 1'b0;
  reg  [31:0] pwdata = 32'h0;
  reg  [3:0]  pstrb = 4'h0;
  reg  [7:0]  gpio_in8 = 8'h00;
  reg  [31:0] gpio_in32 = 32'h0;

  wire [31:0] prdata8, prdata32;
  wire        pready8, pready32, pslverr8, pslverr32;
  wire [7:0]  gpio_out8, gpio_oe8;
  wire [31:0] gpio_out32, gpio_oe32;
  wire        irq8, irq32;

  integer passed = 0;
  integer failed = 0;
  integer cur = 8;
  integer base = 0;
  reg [31:0] pins = 32'hFF;
  reg [8*64-1:0] nonce;

  always #5 pclk = ~pclk;

  apb_gpio #(.ADDR_WIDTH(8), .N(8)) dut8 (
    .pclk(pclk), .presetn(presetn), .paddr(paddr), .psel(psel8), .penable(penable),
    .pwrite(pwrite), .pwdata(pwdata), .pstrb(pstrb), .prdata(prdata8), .pready(pready8),
    .pslverr(pslverr8), .gpio_in(gpio_in8), .gpio_out(gpio_out8), .gpio_oe(gpio_oe8),
    .irq(irq8));

  apb_gpio #(.ADDR_WIDTH(8), .N(32)) dut32 (
    .pclk(pclk), .presetn(presetn), .paddr(paddr), .psel(psel32), .penable(penable),
    .pwrite(pwrite), .pwdata(pwdata), .pstrb(pstrb), .prdata(prdata32), .pready(pready32),
    .pslverr(pslverr32), .gpio_in(gpio_in32), .gpio_out(gpio_out32), .gpio_oe(gpio_oe32),
    .irq(irq32));

  wire [31:0] prdata_s   = (cur == 32) ? prdata32   : prdata8;
  wire        pready_s   = (cur == 32) ? pready32   : pready8;
  wire        pslverr_s  = (cur == 32) ? pslverr32  : pslverr8;
  wire [31:0] gpio_out_s = (cur == 32) ? gpio_out32 : {24'h0, gpio_out8};
  wire [31:0] gpio_oe_s  = (cur == 32) ? gpio_oe32  : {24'h0, gpio_oe8};
  wire        irq_s      = (cur == 32) ? irq32      : irq8;

  // ------------------------------------------------------------ checks
  task check32(input [31:0] act, input [31:0] exp, input [8*48-1:0] what);
    begin
      if (act !== exp) begin
        failed = failed + 1;
        $error("N=%0d %0s: got %h expected %h", cur, what, act, exp);
      end else begin
        passed = passed + 1;
      end
    end
  endtask

  task check1(input act, input exp, input [8*48-1:0] what);
    begin
      if (act !== exp) begin
        failed = failed + 1;
        $error("N=%0d %0s: got %b expected %b", cur, what, act, exp);
      end else begin
        passed = passed + 1;
      end
    end
  endtask

  task finish_run;
    begin
      if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = 0;
      $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
      $finish;
    end
  endtask

  // ------------------------------------------------------------ bus
  task bus_idle;
    begin
      psel8 = 1'b0; psel32 = 1'b0; penable = 1'b0; pwrite = 1'b0;
      paddr = 8'h00; pwdata = 32'h0; pstrb = 4'h0;
    end
  endtask

  task set_pins(input [31:0] v);
    begin
      if (cur == 32) gpio_in32 = v;
      else gpio_in8 = v[7:0];
    end
  endtask

  task pin_change(input [31:0] v);
    begin
      @(negedge pclk);
      set_pins(v);
    end
  endtask

  task apb_write_p(input [7:0] addr, input [31:0] data, input [3:0] strb,
                   input exp_err, input do_pin, input [31:0] pinval);
    begin
      @(negedge pclk);
      psel8 = (cur == 8); psel32 = (cur == 32); penable = 1'b0;
      paddr = addr; pwrite = 1'b1; pwdata = data; pstrb = strb;
      if (do_pin) set_pins(pinval);
      #1;
      check1(pslverr_s, 1'b0, "pslverr low in setup");
      check32(prdata_s, 32'h0, "prdata zero in setup");
      @(negedge pclk);
      penable = 1'b1;
      #1;
      check1(pready_s, 1'b1, "pready high in access");
      check1(pslverr_s, exp_err, "write pslverr");
      @(posedge pclk);
      #1;
      bus_idle;
      #1;
      check1(pslverr_s, 1'b0, "pslverr low when idle");
      check32(prdata_s, 32'h0, "prdata zero when idle");
    end
  endtask

  task apb_write(input [7:0] addr, input [31:0] data, input [3:0] strb, input exp_err);
    begin
      apb_write_p(addr, data, strb, exp_err, 1'b0, 32'h0);
    end
  endtask

  task apb_read(input [7:0] addr, input [31:0] exp, input exp_err, input [8*48-1:0] what);
    begin
      @(negedge pclk);
      psel8 = (cur == 8); psel32 = (cur == 32); penable = 1'b0;
      paddr = addr; pwrite = 1'b0; pwdata = 32'h0; pstrb = 4'h0;
      #1;
      check1(pslverr_s, 1'b0, "pslverr low in setup");
      check32(prdata_s, 32'h0, "prdata zero in setup");
      @(negedge pclk);
      penable = 1'b1;
      #1;
      check1(pready_s, 1'b1, "pready high in access");
      check1(pslverr_s, exp_err, "read pslverr");
      check32(prdata_s, exp, what);
      @(posedge pclk);
      #1;
      bus_idle;
    end
  endtask

  task rd_status(input [31:0] exp);
    begin
      apb_read(A_STAT, exp, 1'b0, "INTR_STATUS");
    end
  endtask

  task do_reset;
    begin
      @(negedge pclk);
      presetn = 1'b0;
      bus_idle;
      gpio_in8 = 8'h00;
      gpio_in32 = 32'h0;
      @(negedge pclk);
      @(negedge pclk);
      check32(gpio_out_s, 32'h0, "gpio_out in reset");
      check32(gpio_oe_s, 32'h0, "gpio_oe in reset");
      check1(irq_s, 1'b0, "irq in reset");
      check32(prdata_s, 32'h0, "prdata in reset");
      check1(pslverr_s, 1'b0, "pslverr in reset");
      presetn = 1'b1;
    end
  endtask

  task check_all_zero;
    begin
      apb_read(A_DOUT, 32'h0, 1'b0, "reset DATA_OUT");
      apb_read(A_DIR,  32'h0, 1'b0, "reset DIR");
      apb_read(A_DIN,  32'h0, 1'b0, "reset DATA_IN");
      apb_read(A_RISE, 32'h0, 1'b0, "reset INTR_RISE");
      apb_read(A_FALL, 32'h0, 1'b0, "reset INTR_FALL");
      apb_read(A_HIGH, 32'h0, 1'b0, "reset INTR_HIGH");
      apb_read(A_LOW,  32'h0, 1'b0, "reset INTR_LOW");
      apb_read(A_EN,   32'h0, 1'b0, "reset INTR_ENABLE");
      apb_read(A_STAT, 32'h0, 1'b0, "reset INTR_STATUS");
      check32(gpio_out_s, 32'h0, "reset gpio_out");
      check32(gpio_oe_s, 32'h0, "reset gpio_oe");
      check1(irq_s, 1'b0, "reset irq");
    end
  endtask

  task test_rw(input [7:0] addr, input [8*48-1:0] what);
    reg [31:0] e, m;
    begin
      apb_write(addr, 32'hA5A5_A5A5, 4'hF, 1'b0);
      e = 32'hA5A5_A5A5 & pins;
      apb_read(addr, e, 1'b0, what);
      apb_write(addr, 32'h5A3C_C35A, 4'b0101, 1'b0);
      m = 32'h00FF_00FF & pins;
      e = (e & ~m) | (32'h5A3C_C35A & m);
      apb_read(addr, e, 1'b0, what);
      if (addr == A_DOUT) check32(gpio_out_s, e, "gpio_out follows DATA_OUT");
      if (addr == A_DIR)  check32(gpio_oe_s, e, "gpio_oe follows DIR");
      apb_write(addr, 32'hFFFF_FFFF, 4'b0000, 1'b0);
      apb_read(addr, e, 1'b0, what);
      apb_write(addr, 32'h0, 4'hF, 1'b0);
      apb_read(addr, 32'h0, 1'b0, what);
      if (addr == A_DOUT) check32(gpio_out_s, 32'h0, "gpio_out cleared");
      if (addr == A_DIR)  check32(gpio_oe_s, 32'h0, "gpio_oe cleared");
    end
  endtask

  // ------------------------------------------------------------ suite
  task run_suite;
    reg [31:0] v, e2, pv, b0, b1, b2, b3, b4, b5, ed;
    reg [3:0] sx;
    begin
      pins = (cur == 32) ? 32'hFFFF_FFFF : 32'h0000_00FF;
      base = (cur == 32) ? 24 : 0;
      b0 = 32'h0000_0001 << base;
      b1 = 32'h0000_0002 << base;
      b2 = 32'h0000_0004 << base;
      b3 = 32'h0000_0008 << base;
      b4 = 32'h0000_0010 << base;
      b5 = 32'h0000_0020 << base;
      sx = ~(4'b0001 << (base / 8));

      // Reset values.
      do_reset;
      check_all_zero;

      // Read/write registers, partial strobes, bits above N.
      test_rw(A_DOUT, "DATA_OUT");
      test_rw(A_DIR,  "DIR");
      test_rw(A_RISE, "INTR_RISE");
      test_rw(A_FALL, "INTR_FALL");
      test_rw(A_HIGH, "INTR_HIGH");
      test_rw(A_EN,   "INTR_ENABLE");
      test_rw(A_LOW,  "INTR_LOW");
      check1(irq_s, 1'b0, "irq low while INTR_ENABLE zero");
      e2 = (32'hA5A5_A5A5 & ~32'h00FF_00FF) | (32'h5A3C_C35A & 32'h00FF_00FF);
      apb_read(A_STAT, (32'hA5A5_A5A5 | e2) & pins, 1'b0, "status after INTR_LOW test");
      apb_write(A_STAT, 32'hFFFF_FFFF, 4'hF, 1'b0);
      rd_status(32'h0);

      // DATA_IN: sampled, read only.
      v = 32'hDEAD_BEEF & pins;
      pin_change(v);
      apb_read(A_DIN, v, 1'b0, "DATA_IN sample");
      apb_write(A_DIR, 32'hFFFF_FFFF, 4'hF, 1'b0);
      apb_write(A_DOUT, ~v, 4'hF, 1'b0);
      check32(gpio_oe_s, pins, "gpio_oe all outputs");
      check32(gpio_out_s, ~v & pins, "gpio_out value");
      apb_read(A_DIN, v, 1'b0, "DATA_IN with outputs enabled");
      apb_write(A_DIN, 32'hFFFF_FFFF, 4'hF, 1'b1);
      apb_write(A_DIN, 32'h0, 4'h3, 1'b1);
      apb_read(A_DIN, v, 1'b0, "DATA_IN after write");
      pin_change(32'h0);
      apb_read(A_DIN, 32'h0, 1'b0, "DATA_IN follows pins");
      apb_write(A_DOUT, 32'h0, 4'hF, 1'b0);
      apb_write(A_DIR, 32'h0, 4'hF, 1'b0);
      rd_status(32'h0);

      // PSLVERR policy and unmapped addresses.
      apb_write(A_DOUT, 32'h1234_5678, 4'hF, 1'b0);
      apb_write(8'h24, 32'hFFFF_FFFF, 4'hF, 1'b1);
      apb_write(8'h28, 32'hFFFF_FFFF, 4'hF, 1'b1);
      apb_write(8'h3C, 32'hFFFF_FFFF, 4'hF, 1'b1);
      apb_write(8'h01, 32'hFFFF_FFFF, 4'hF, 1'b1);
      apb_write(8'h02, 32'hFFFF_FFFF, 4'hF, 1'b1);
      apb_write(8'h03, 32'hFFFF_FFFF, 4'hF, 1'b1);
      apb_write(8'h05, 32'hFFFF_FFFF, 4'hF, 1'b1);
      apb_write(8'h40, 32'hFFFF_FFFF, 4'hF, 1'b1);
      apb_write(8'h44, 32'hFFFF_FFFF, 4'hF, 1'b1);
      apb_write(8'h5C, 32'hFFFF_FFFF, 4'hF, 1'b1);
      apb_write(8'h80, 32'hFFFF_FFFF, 4'hF, 1'b1);
      apb_write(8'hFC, 32'hFFFF_FFFF, 4'hF, 1'b1);
      apb_read(A_DOUT, 32'h1234_5678 & pins, 1'b0, "DATA_OUT after unmapped writes");
      check32(gpio_out_s, 32'h1234_5678 & pins, "gpio_out after unmapped writes");
      apb_read(A_DIR,  32'h0, 1'b0, "DIR after unmapped writes");
      apb_read(A_RISE, 32'h0, 1'b0, "INTR_RISE after unmapped writes");
      apb_read(A_FALL, 32'h0, 1'b0, "INTR_FALL after unmapped writes");
      apb_read(A_HIGH, 32'h0, 1'b0, "INTR_HIGH after unmapped writes");
      apb_read(A_LOW,  32'h0, 1'b0, "INTR_LOW after unmapped writes");
      apb_read(A_EN,   32'h0, 1'b0, "INTR_ENABLE after unmapped writes");
      rd_status(32'h0);
      apb_read(8'h01, 32'h0, 1'b1, "unaligned read 0x01");
      apb_read(8'h02, 32'h0, 1'b1, "unaligned read 0x02");
      apb_read(8'h03, 32'h0, 1'b1, "unaligned read 0x03");
      apb_read(8'h21, 32'h0, 1'b1, "unaligned read 0x21");
      apb_read(8'h24, 32'h0, 1'b1, "unmapped read 0x24");
      apb_read(8'h3C, 32'h0, 1'b1, "unmapped read 0x3C");
      apb_read(8'h40, 32'h0, 1'b1, "aliased read 0x40");
      apb_read(8'h80, 32'h0, 1'b1, "aliased read 0x80");
      apb_read(8'hFC, 32'h0, 1'b1, "unmapped read 0xFC");
      apb_write(A_DOUT, 32'h0, 4'hF, 1'b0);

      // Rising edge: fires once; partial-strobe and write-0 do not clear.
      pv = 32'h0;
      apb_write(A_RISE, b0 | b4 | b5, 4'hF, 1'b0);
      rd_status(32'h0);
      pv = pv | b0;
      pin_change(pv);
      rd_status(b0);
      apb_write(A_STAT, 32'hFFFF_FFFF, sx, 1'b0);
      rd_status(b0);
      apb_write(A_STAT, 32'h0, 4'hF, 1'b0);
      rd_status(b0);
      apb_write(A_STAT, b0, 4'hF, 1'b0);
      rd_status(32'h0);
      rd_status(32'h0);

      // Falling edge.
      apb_write(A_FALL, b1, 4'hF, 1'b0);
      pv = pv | b1;
      pin_change(pv);
      rd_status(32'h0);
      pv = pv & ~b1;
      pin_change(pv);
      rd_status(b1);

      // High level: a clear does not stick while the level holds.
      apb_write(A_HIGH, b2, 4'hF, 1'b0);
      pv = pv | b2;
      pin_change(pv);
      rd_status(b1 | b2);
      apb_write(A_STAT, b2, 4'hF, 1'b0);
      rd_status(b1 | b2);
      apb_write(A_STAT, b1, 4'hF, 1'b0);
      rd_status(b2);
      pv = pv & ~b2;
      pin_change(pv);
      apb_write(A_STAT, b2, 4'hF, 1'b0);
      rd_status(32'h0);

      // Low level and the interrupt mask.
      apb_write(A_LOW, b3, 4'hF, 1'b0);
      rd_status(b3);
      check1(irq_s, 1'b0, "irq masked with status pending");
      apb_write(A_EN, b3, 4'hF, 1'b0);
      check1(irq_s, 1'b1, "irq on unmask of pending bit");
      apb_write(A_EN, b0, 4'hF, 1'b0);
      check1(irq_s, 1'b0, "irq low, other bit enabled");
      rd_status(b3);
      apb_write(A_EN, b3 | b0, 4'hF, 1'b0);
      check1(irq_s, 1'b1, "irq high again");
      apb_write(A_STAT, b3, 4'hF, 1'b0);
      rd_status(b3);
      check1(irq_s, 1'b1, "irq held while level holds");
      pv = pv | b3;
      pin_change(pv);
      apb_write(A_STAT, b3, 4'hF, 1'b0);
      rd_status(32'h0);
      check1(irq_s, 1'b0, "irq low after clear");

      // One-cycle pulses: rise on pin 5, fall on pin 1.
      pin_change(pv | b5);
      pin_change(pv);
      rd_status(b5);
      check1(irq_s, 1'b0, "masked rise does not raise irq");
      apb_write(A_EN, b5 | b3 | b0, 4'hF, 1'b0);
      check1(irq_s, 1'b1, "irq after unmasking rise");
      apb_write(A_STAT, b5, 4'hF, 1'b0);
      rd_status(32'h0);
      check1(irq_s, 1'b0, "irq low after rise clear");
      pin_change(pv | b1);
      pin_change(pv);
      rd_status(b1);
      apb_write(A_STAT, b1, 4'hF, 1'b0);
      rd_status(32'h0);

      // A detection beats a clear on the same edge.
      pv = pv | b4;
      pin_change(pv);
      rd_status(b4);
      pv = pv & ~b4;
      pin_change(pv);
      rd_status(b4);
      pv = pv | b4;
      apb_write_p(A_STAT, b4, 4'hF, 1'b0, 1'b1, pv);
      rd_status(b4);
      apb_write(A_STAT, b4, 4'hF, 1'b0);
      rd_status(32'h0);

      // Cleanup.
      apb_write(A_RISE, 32'h0, 4'hF, 1'b0);
      apb_write(A_FALL, 32'h0, 4'hF, 1'b0);
      apb_write(A_HIGH, 32'h0, 4'hF, 1'b0);
      apb_write(A_LOW,  32'h0, 4'hF, 1'b0);
      apb_write(A_EN,   32'h0, 4'hF, 1'b0);
      pin_change(32'h0);
      apb_write(A_STAT, 32'hFFFF_FFFF, 4'hF, 1'b0);
      rd_status(32'h0);

      // Reset again, from a busy state.
      apb_write(A_DOUT, 32'hFFFF_FFFF, 4'hF, 1'b0);
      apb_write(A_DIR,  32'hFFFF_FFFF, 4'hF, 1'b0);
      apb_write(A_EN,   32'hFFFF_FFFF, 4'hF, 1'b0);
      apb_write(A_LOW,  32'hFFFF_FFFF, 4'hF, 1'b0);
      rd_status(pins);
      check1(irq_s, 1'b1, "irq before second reset");
      ed = pins;
      check32(gpio_out_s, ed, "gpio_out before second reset");
      do_reset;
      check_all_zero;
    end
  endtask

  // ------------------------------------------------------------ main
  initial begin
    bus_idle;
    cur = 8;
    run_suite;
    cur = 32;
    run_suite;
    finish_run;
  end

  initial begin
    #2000000;
    failed = failed + 1;
    $error("timeout");
    finish_run;
  end

endmodule
